// Lesson: vLLM Serving Internals (phase 17 / lesson 04)
// Rust port of code/main.py. Standard library only.
// Source: phases/17-infrastructure-and-production/04-vllm-serving-internals/docs/en.md
// Build: rustc --edition 2021 -O code/main.rs -o /tmp/lesson && /tmp/lesson

use std::collections::VecDeque;

const FORWARD_LATENCY_PER_TOKEN: f64 = 0.0005;
const PREFILL_LATENCY_PER_TOKEN: f64 = 0.00004;
const BATCH_OVERHEAD: f64 = 0.0002;
const CHUNK_SIZE: usize = 512;
const KV_BLOCK_SIZE: usize = 16;
const KV_BLOCKS_AVAILABLE: usize = 1800;

struct Rng(u64);

impl Rng {
    fn new(seed: u64) -> Self {
        Rng(seed)
    }
    fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }
    fn random(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 / (1u64 << 53) as f64
    }
    fn expovariate(&mut self, lambd: f64) -> f64 {
        -(1.0 - self.random()).ln() / lambd
    }
    fn randint(&mut self, lo: usize, hi: usize) -> usize {
        lo + (self.next_u64() % (hi - lo + 1) as u64) as usize
    }
    fn choice<T: Copy>(&mut self, xs: &[T]) -> T {
        xs[(self.next_u64() % xs.len() as u64) as usize]
    }
}

#[derive(Clone)]
struct Request {
    prompt_len: usize,
    output_len: usize,
    arrived_at: f64,
    prefilled: usize,
    generated: usize,
    ttft: Option<f64>,
    last_token_at: Option<f64>,
    itl_samples: Vec<f64>,
}

impl Request {
    fn new(prompt_len: usize, output_len: usize, arrived_at: f64) -> Self {
        Request {
            prompt_len,
            output_len,
            arrived_at,
            prefilled: 0,
            generated: 0,
            ttft: None,
            last_token_at: None,
            itl_samples: Vec::new(),
        }
    }
    fn in_prefill(&self) -> bool {
        self.prefilled < self.prompt_len
    }
    fn done(&self) -> bool {
        self.generated >= self.output_len
    }
    fn blocks_needed(&self) -> usize {
        let total = self.prompt_len + self.output_len;
        total.div_ceil(KV_BLOCK_SIZE)
    }
}

fn make_workload(n: usize, seed: u64) -> Vec<Request> {
    let mut rng = Rng::new(seed);
    let mut reqs = Vec::new();
    let mut now = 0.0;
    for _ in 0..n {
        now += rng.expovariate(40.0);
        let prompt_len = rng.choice(&[128, 256, 512, 2048, 8192]);
        let out_len = rng.randint(50, 300);
        reqs.push(Request::new(prompt_len, out_len, now));
    }
    reqs
}

fn report(label: &str, reqs: &[Request], sim_end: f64) {
    let ttfts: Vec<f64> = reqs.iter().filter_map(|r| r.ttft.map(|t| t - r.arrived_at)).collect();
    let mut itls: Vec<f64> = reqs.iter().flat_map(|r| r.itl_samples.iter().copied()).collect();
    let total_out: usize = reqs.iter().map(|r| r.generated).sum();
    let throughput = if sim_end != 0.0 { total_out as f64 / sim_end } else { 0.0 };
    let mean_ttft = if ttfts.is_empty() { 0.0 } else { ttfts.iter().sum::<f64>() / ttfts.len() as f64 * 1000.0 };
    let p99_itl = if itls.is_empty() {
        0.0
    } else {
        itls.sort_by(|a, b| a.partial_cmp(b).unwrap());
        let idx = (0.99 * itls.len() as f64) as isize - 1;
        let idx = if idx < 0 { itls.len() as isize + idx } else { idx } as usize;
        itls[idx] * 1000.0
    };
    let finished = reqs.iter().filter(|r| r.done()).count();
    println!(
        "{:<28}  throughput={:6.0} tok/s   mean_TTFT={:6.1} ms   P99_ITL={:5.1} ms   finished={}/{}",
        label,
        throughput,
        mean_ttft,
        p99_itl,
        finished,
        reqs.len()
    );
}

fn simulate_naive(reqs: &mut [Request]) -> f64 {
    let mut now: f64 = 0.0;
    for r in reqs.iter_mut() {
        if now < r.arrived_at {
            now = r.arrived_at;
        }
        now += r.prompt_len as f64 * PREFILL_LATENCY_PER_TOKEN + BATCH_OVERHEAD;
        r.prefilled = r.prompt_len;
        r.ttft = Some(now);
        r.last_token_at = Some(now);
        for _ in 0..r.output_len {
            let prev = r.last_token_at.unwrap();
            now += FORWARD_LATENCY_PER_TOKEN + BATCH_OVERHEAD;
            r.generated += 1;
            r.itl_samples.push(now - prev);
            r.last_token_at = Some(now);
        }
    }
    now
}

fn simulate_static(reqs: &mut [Request], batch: usize) -> f64 {
    let mut now: f64 = 0.0;
    let mut i = 0;
    while i < reqs.len() {
        let end = (i + batch).min(reqs.len());
        let window = &mut reqs[i..end];
        i += batch;
        let latest = window.iter().map(|r| r.arrived_at).fold(f64::NEG_INFINITY, f64::max);
        now = now.max(latest);
        let pad_prompt = window.iter().map(|r| r.prompt_len).max().unwrap();
        let pad_output = window.iter().map(|r| r.output_len).max().unwrap();
        now += pad_prompt as f64 * PREFILL_LATENCY_PER_TOKEN + BATCH_OVERHEAD;
        for r in window.iter_mut() {
            r.prefilled = r.prompt_len;
            r.ttft = Some(now);
            r.last_token_at = Some(now);
        }
        let width = window.len() as f64;
        for _ in 0..pad_output {
            let prev_now = now;
            now += FORWARD_LATENCY_PER_TOKEN * width / 16.0 + BATCH_OVERHEAD;
            for r in window.iter_mut() {
                if r.generated < r.output_len {
                    r.generated += 1;
                    r.itl_samples.push(now - prev_now);
                    r.last_token_at = Some(now);
                }
            }
        }
    }
    now
}

fn truthy(x: Option<f64>) -> Option<f64> {
    x.filter(|v| *v != 0.0)
}

fn simulate_continuous(reqs: &mut [Request], chunked: bool) -> f64 {
    let mut order: Vec<usize> = (0..reqs.len()).collect();
    order.sort_by(|&a, &b| reqs[a].arrived_at.partial_cmp(&reqs[b].arrived_at).unwrap());
    let mut waiting: VecDeque<usize> = order.into_iter().collect();
    let mut running: Vec<usize> = Vec::new();
    let mut blocks_used = 0;
    let mut now: f64 = 0.0;
    while !waiting.is_empty() || !running.is_empty() {
        while let Some(&w) = waiting.front() {
            if reqs[w].arrived_at > now {
                break;
            }
            if blocks_used + reqs[w].blocks_needed() > KV_BLOCKS_AVAILABLE {
                break;
            }
            blocks_used += reqs[w].blocks_needed();
            running.push(waiting.pop_front().unwrap());
        }
        if running.is_empty() {
            match waiting.front() {
                None => break,
                Some(&w) => {
                    now = reqs[w].arrived_at;
                    continue;
                }
            }
        }

        let mut batch_tokens = 0;
        let mut prefill_work = 0;
        let mut decoded: Vec<usize> = Vec::new();
        for &ri in &running {
            let r = &mut reqs[ri];
            if r.in_prefill() {
                let remaining = r.prompt_len - r.prefilled;
                let take = if chunked { CHUNK_SIZE.min(remaining) } else { remaining };
                r.prefilled += take;
                prefill_work += take;
                if r.prefilled >= r.prompt_len {
                    r.ttft = Some(now + prefill_work as f64 * PREFILL_LATENCY_PER_TOKEN);
                }
            } else {
                decoded.push(ri);
                batch_tokens += 1;
            }
        }

        let dt = prefill_work as f64 * PREFILL_LATENCY_PER_TOKEN
            + batch_tokens as f64 * FORWARD_LATENCY_PER_TOKEN
            + BATCH_OVERHEAD;
        now += dt;
        for &ri in &decoded {
            let r = &mut reqs[ri];
            let prev = truthy(r.last_token_at).or(truthy(r.ttft)).unwrap_or(now);
            r.generated += 1;
            r.itl_samples.push(now - prev);
            r.last_token_at = Some(now);
            if r.ttft.is_none() {
                r.ttft = Some(now);
            }
        }

        let mut kept = Vec::new();
        for &ri in &running {
            if reqs[ri].done() {
                blocks_used -= reqs[ri].blocks_needed();
            } else {
                kept.push(ri);
            }
        }
        running = kept;
    }
    now
}

fn fresh(base: &[Request]) -> Vec<Request> {
    base.iter().map(|r| Request::new(r.prompt_len, r.output_len, r.arrived_at)).collect()
}

fn main() {
    println!("{}", "=".repeat(80));
    println!("TOY vLLM SCHEDULER: four modes on the same 60-request workload");
    println!("{}", "=".repeat(80));

    let base = make_workload(60, 7);
    let mut w1 = fresh(&base);
    let end = simulate_naive(&mut w1);
    report("NAIVE", &w1, end);

    let mut w2 = fresh(&base);
    let end = simulate_static(&mut w2, 16);
    report("STATIC (batch=16, padded)", &w2, end);

    let mut w3 = fresh(&base);
    let end = simulate_continuous(&mut w3, false);
    report("CONTINUOUS (no chunk)", &w3, end);

    let mut w4 = fresh(&base);
    let end = simulate_continuous(&mut w4, true);
    report("CONTINUOUS + CHUNKED", &w4, end);

    println!();
    println!("Read the CONTINUOUS+CHUNKED row. That is what vLLM ships as default.");
    println!("The gap between STATIC and CONTINUOUS is the whole reason vLLM exists.");
}

// Lesson: Serving Engine Internals: PagedAttention, Continuous Batching, Chunked Prefill (phase 17 / lesson 04)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/17-infrastructure-and-production/04-vllm-serving-internals/docs/en.md
// Run: npx tsx phases/17-infrastructure-and-production/04-vllm-serving-internals/code/main.ts

function fixed(x: number, digits: number): string {
  const rounded = x.toFixed(digits);
  if (Math.abs(x) >= 1e21) return rounded;
  const exact = x.toFixed(100);
  const dot = exact.indexOf(".");
  if (!/^50*$/.test(exact.slice(dot + 1 + digits))) return rounded;
  const kept = digits === 0 ? exact.slice(0, dot) : exact.slice(0, dot + 1 + digits);
  return Number(kept.slice(-1)) % 2 === 0 ? kept : rounded;
}

const rj = (s: string | number, w: number): string => String(s).padStart(w);
const lj = (s: string, w: number): string => s.padEnd(w);

class Rng {
  private state: number;

  constructor(seed: number) {
    this.state = seed >>> 0;
  }

  random(): number {
    this.state = (this.state + 0x6d2b79f5) >>> 0;
    let t = this.state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  expovariate(lambd: number): number {
    return -Math.log(1.0 - this.random()) / lambd;
  }

  choice<T>(xs: T[]): T {
    return xs[Math.floor(this.random() * xs.length)];
  }

  randint(a: number, b: number): number {
    return a + Math.floor(this.random() * (b - a + 1));
  }
}

const FORWARD_LATENCY_PER_TOKEN = 0.0005;
const PREFILL_LATENCY_PER_TOKEN = 0.00004;
const BATCH_OVERHEAD = 0.0002;
const CHUNK_SIZE = 512;
const KV_BLOCK_SIZE = 16;
const KV_BLOCKS_AVAILABLE = 1800;

class Request {
  prefilled = 0;
  generated = 0;
  ttft: number | null = null;
  lastTokenAt: number | null = null;
  itlSamples: number[] = [];

  constructor(
    public reqId: number,
    public promptLen: number,
    public outputLen: number,
    public arrivedAt: number,
  ) {}

  get inPrefill(): boolean {
    return this.prefilled < this.promptLen;
  }

  get done(): boolean {
    return this.generated >= this.outputLen;
  }

  blocksNeeded(): number {
    const total = this.promptLen + this.outputLen;
    return Math.floor((total + KV_BLOCK_SIZE - 1) / KV_BLOCK_SIZE);
  }
}

function makeWorkload(n = 60, seed = 9): Request[] {
  const rng = new Rng(seed);
  const reqs: Request[] = [];
  let now = 0.0;
  for (let i = 0; i < n; i++) {
    now += rng.expovariate(40.0);
    const promptLen = rng.choice([128, 256, 512, 2048, 8192]);
    const outLen = rng.randint(50, 300);
    reqs.push(new Request(i, promptLen, outLen, now));
  }
  return reqs;
}

function report(label: string, reqs: Request[], simEnd: number): void {
  const ttfts = reqs.filter((r) => r.ttft !== null).map((r) => (r.ttft ?? 0) - r.arrivedAt);
  const itls = reqs.flatMap((r) => r.itlSamples);
  const totalOut = reqs.reduce((acc, r) => acc + r.generated, 0);
  const throughput = simEnd ? totalOut / simEnd : 0;
  const meanTtft = ttfts.length ? (ttfts.reduce((a, b) => a + b, 0) / ttfts.length) * 1000 : 0;
  const sortedItls = [...itls].sort((a, b) => a - b);
  const p99Itl = itls.length ? sortedItls[Math.trunc(0.99 * itls.length) - 1] * 1000 : 0;
  const finished = reqs.filter((r) => r.done).length;
  console.log(
    `${lj(label, 28)}  throughput=${rj(fixed(throughput, 0), 6)} tok/s   ` +
      `mean_TTFT=${rj(fixed(meanTtft, 1), 6)} ms   ` +
      `P99_ITL=${rj(fixed(p99Itl, 1), 5)} ms   finished=${finished}/${reqs.length}`,
  );
}

function simulateNaive(reqs: Request[]): number {
  let now = 0.0;
  for (const r of reqs) {
    if (now < r.arrivedAt) now = r.arrivedAt;
    now += r.promptLen * PREFILL_LATENCY_PER_TOKEN + BATCH_OVERHEAD;
    r.prefilled = r.promptLen;
    r.ttft = now;
    r.lastTokenAt = now;
    for (let k = 0; k < r.outputLen; k++) {
      const prev = r.lastTokenAt;
      now += FORWARD_LATENCY_PER_TOKEN + BATCH_OVERHEAD;
      r.generated += 1;
      r.itlSamples.push(now - prev);
      r.lastTokenAt = now;
    }
  }
  return now;
}

function simulateStatic(reqs: Request[], batch = 16): number {
  let now = 0.0;
  let i = 0;
  while (i < reqs.length) {
    const window = reqs.slice(i, i + batch);
    i += batch;
    now = Math.max(now, Math.max(...window.map((r) => r.arrivedAt)));
    const padPrompt = Math.max(...window.map((r) => r.promptLen));
    const padOutput = Math.max(...window.map((r) => r.outputLen));
    now += padPrompt * PREFILL_LATENCY_PER_TOKEN + BATCH_OVERHEAD;
    for (const r of window) {
      r.prefilled = r.promptLen;
      r.ttft = now;
      r.lastTokenAt = now;
    }
    for (let k = 0; k < padOutput; k++) {
      const prevNow = now;
      now += (FORWARD_LATENCY_PER_TOKEN * window.length) / 16 + BATCH_OVERHEAD;
      for (const r of window) {
        if (r.generated < r.outputLen) {
          r.generated += 1;
          r.itlSamples.push(now - prevNow);
          r.lastTokenAt = now;
        }
      }
    }
  }
  return now;
}

function simulateContinuous(reqs: Request[], chunked: boolean): number {
  const waiting = [...reqs].sort((a, b) => a.arrivedAt - b.arrivedAt);
  let running: Request[] = [];
  let blocksUsed = 0;
  let now = 0.0;
  while (waiting.length || running.length) {
    if (waiting.length && running.length && now < waiting[0].arrivedAt && !running.length) {
      now = waiting[0].arrivedAt;
    }
    while (waiting.length && waiting[0].arrivedAt <= now) {
      const r = waiting[0];
      if (blocksUsed + r.blocksNeeded() > KV_BLOCKS_AVAILABLE) break;
      blocksUsed += r.blocksNeeded();
      running.push(waiting.shift() as Request);
    }
    if (!running.length) {
      if (!waiting.length) break;
      now = waiting[0].arrivedAt;
      continue;
    }

    let batchTokens = 0;
    let prefillWork = 0;
    const decoded: Request[] = [];
    for (const r of running) {
      if (r.inPrefill) {
        const remaining = r.promptLen - r.prefilled;
        const take = Math.min(chunked ? CHUNK_SIZE : remaining, remaining);
        r.prefilled += take;
        prefillWork += take;
        if (r.prefilled >= r.promptLen) r.ttft = now + prefillWork * PREFILL_LATENCY_PER_TOKEN;
      } else {
        decoded.push(r);
        batchTokens += 1;
      }
    }

    const dt = prefillWork * PREFILL_LATENCY_PER_TOKEN + batchTokens * FORWARD_LATENCY_PER_TOKEN + BATCH_OVERHEAD;
    now += dt;
    for (const r of decoded) {
      const prev = r.lastTokenAt || r.ttft || now;
      r.generated += 1;
      r.itlSamples.push(now - prev);
      r.lastTokenAt = now;
      if (r.ttft === null) r.ttft = now;
    }

    const finished = running.filter((r) => r.done);
    for (const r of finished) blocksUsed -= r.blocksNeeded();
    running = running.filter((r) => !r.done);
  }
  return now;
}

function copy(base: Request[]): Request[] {
  return base.map((r) => new Request(r.reqId, r.promptLen, r.outputLen, r.arrivedAt));
}

function main(): void {
  console.log("=".repeat(80));
  console.log("TOY vLLM SCHEDULER: four modes on the same 60-request workload");
  console.log("=".repeat(80));

  const base = makeWorkload();
  const w1 = copy(base);
  report("NAIVE", w1, simulateNaive(w1));

  const w2 = copy(base);
  report("STATIC (batch=16, padded)", w2, simulateStatic(w2));

  const w3 = copy(base);
  report("CONTINUOUS (no chunk)", w3, simulateContinuous(w3, false));

  const w4 = copy(base);
  report("CONTINUOUS + CHUNKED", w4, simulateContinuous(w4, true));

  console.log();
  console.log("Read the CONTINUOUS+CHUNKED row. That is what vLLM ships as default.");
  console.log("The gap between STATIC and CONTINUOUS is the whole reason vLLM exists.");
}

main();
